// src/components/FlashDealSection.jsx
"use client";

import { useState, useEffect } from "react";

export default function FlashDealSection() {
  const [deals, setDeals] = useState([]);
  const [timeLifts, setTimeLifts] = useState({});

  useEffect(() => {
    fetchDeals();
  }, []);

  const fetchDeals = async () => {
    try {
      const res = await fetch("/api/admin/flash-deals");
      const data = await res.json();
      if (data.success) {
        setDeals(data.flashDeals || []);
      }
    } catch (err) {
      console.error("Error fetching flash deals:", err);
    }
  };

  useEffect(() => {
    if (deals.length === 0) return;

    const timer = setInterval(() => {
      const now = new Date().getTime();
      const updatedTimes = {};
      let hasExpired = false;

      deals.forEach((deal) => {
        const distance = new Date(deal.flashExpiresAt).getTime() - now;
        if (distance < 0) {
          updatedTimes[deal._id] = "EXPIRED";
          hasExpired = true;
        } else {
          const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
          const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
          const seconds = Math.floor((distance % (1000 * 60)) / 1000);
          updatedTimes[deal._id] = `${hours}h ${minutes}m ${seconds}s`;
        }
      });

      setTimeLifts(updatedTimes);

      // If any deal expired, refetch to sync with DB auto-revert
      if (hasExpired) {
        fetchDeals();
      }
    }, 1000);

    return () => clearInterval(timer);
  }, [deals]);

  if (deals.length === 0) return null;

  return (
    <div style={{ margin: "20px 0" }}>
      <h2 style={{ fontSize: "20px", fontWeight: "800", marginBottom: "12px", color: "#1e293b" }}>⚡ Flash Deals</h2>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: "16px" }}>
        {deals.map((deal) => (
          <div key={deal._id} style={{ background: "linear-gradient(135deg, #6366f1 0%, #4f46e5 100%)", color: "#fff", padding: "20px", borderRadius: "16px", display: "flex", flexDirection: "column", justifyContent: "space-between", gap: "16px" }}>
            <div>
              <span style={{ background: "#ef4444", padding: "4px 8px", borderRadius: "6px", fontSize: "11px", fontWeight: "800", textTransform: "uppercase" }}>Limited Time</span>
              <h3 style={{ fontSize: "18px", fontWeight: "800", margin: "8px 0 4px 0" }}>{deal.title}</h3>
              <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                <span style={{ fontSize: "20px", fontWeight: "900" }}>₹{deal.flashPrice}</span>
                <span style={{ fontSize: "14px", textDecoration: "line-through", opacity: 0.8 }}>₹{deal.originalPrice}</span>
              </div>
            </div>
            <div style={{ background: "rgba(255,255,255,0.1)", padding: "10px", borderRadius: "10px", textAlign: "center" }}>
              <div style={{ fontSize: "11px", opacity: 0.9, marginBottom: "2px" }}>Ends in</div>
              <div style={{ fontSize: "16px", fontWeight: "800", letterSpacing: "1px" }}>{timeLifts[deal._id] || "Loading..."}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}